Exacto. Ese es el error más común con while anidados: olvidar reiniciar el contador interno. Si lo pones fuera, ¿qué pasaría con el segundo cliente?

Miremos el código:

```c
printf("Cantidad de clientes: ");
scanf("%d", &nClientes);
float totalGeneral = 0;
int contCliente = 1;

while (contCliente <= nClientes) {
    printf("\n--- Cliente #%d ---\n", contCliente);
    printf("Cantidad de articulos: ");
    scanf("%d", &nArticulos);

    float totalCliente = 0;
    int contArticulo = 1;

    while (contArticulo <= nArticulos) {
        float precio;
        int cantidad;
        printf("  Articulo #%d - Precio: ", contArticulo);
        scanf("%f", &precio);
        printf("  Articulo #%d - Cantidad: ", contArticulo);
        scanf("%d", &cantidad);
        totalCliente = totalCliente + (precio * cantidad);
        contArticulo = contArticulo + 1;
    }

    printf("Total del cliente #%d: %.2f\n", contCliente, totalCliente);
    totalGeneral = totalGeneral + totalCliente;
    contCliente = contCliente + 1;
}
printf("Total general vendido: %.2f\n", totalGeneral);
```

Si moviera la línea `float totalCliente = 0;` fuera del while de clientes, ¿qué pasaría?
